"use strict";
const fs = require("node:fs");
const path = require("node:path");
const root = path.join(__dirname, "..");
const langs = ["en", "de", "zh-Hant"];
const entries = Object.fromEntries(langs.map(x => [x, require(path.join(root, "src/locales", x + ".json"))]));
const keys = Object.keys(entries.en).filter(x => x.startsWith("installer.")).sort();
const quote = value => '"' + String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\r/g, "\\r") + '"';
const lines = [
  "// Generated by scripts/i18n-installer-build.js. Edit src/locales/*.json instead.",
  "using System;",
  "using System.Collections.Generic;",
  "using System.Globalization;",
  "internal static class InstallerLanguage {",
  "  private static readonly Dictionary<string, Dictionary<string,string>> Strings = new Dictionary<string, Dictionary<string,string>> {"
];
for (const lang of langs) {
  lines.push("    { " + quote(lang) + ", new Dictionary<string,string> {");
  for (const key of keys) lines.push("      { " + quote(key) + ", " + quote(entries[lang][key]) + " },");
  lines.push("    } },");
}
lines.push("  };");
lines.push("  private static string Current { get { string lang = CultureInfo.CurrentUICulture.Name; if (lang.StartsWith(\"zh\", StringComparison.OrdinalIgnoreCase)) return \"zh-Hant\"; if (lang.StartsWith(\"de\", StringComparison.OrdinalIgnoreCase)) return \"de\"; return \"en\"; } }");
lines.push("  public static string T(string key) { string result; if (Strings[Current].TryGetValue(key, out result)) return result; return Strings[\"en\"].TryGetValue(key, out result) ? result : key; }");
lines.push("  public static string Format(string key, Dictionary<string,string> values) { string result = T(key); foreach(var entry in values) result = result.Replace(\"{\" + entry.Key + \"}\", entry.Value); return result; }");
lines.push("}");
fs.writeFileSync(path.join(root, "build", "installer-language.generated.cs"), "\uFEFF" + lines.join("\n") + "\n", "utf8");
console.log(`[i18n] Generated installer resources: ${keys.length} keys, ${langs.join(", ")}`);
